using System.ComponentModel;
using System.Text;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace ApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap a REST API via HttpClient.
/// Uses constructor injection — the SDK resolves HttpClient from DI automatically.
/// Only parameters with [Description] appear in the tool schema; DI services and
/// CancellationToken are injected behind the scenes.
/// </summary>
[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("Retrieve a resource by its ID from the REST API.")]
    public async Task<string> GetResource(
        [Description("The unique identifier of the resource to retrieve")] string id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("GET /api/resources/{Id}", id);
        var response = await httpClient.GetAsync($"api/resources/{id}", cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool, Description("List resources with optional filtering. Returns a JSON array.")]
    public async Task<string> ListResources(
        [Description("Optional search query to filter results")] string? query = null,
        [Description("Maximum number of results to return (1-100)")] int limit = 20,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("GET /api/resources?query={Query}&limit={Limit}", query, limit);
        var url = $"api/resources?limit={limit}";
        if (!string.IsNullOrEmpty(query))
            url += $"&query={Uri.EscapeDataString(query)}";

        var response = await httpClient.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool(Destructive = false, ReadOnly = false),
     Description("Create a new resource. Returns the created resource as JSON.")]
    public async Task<string> CreateResource(
        [Description("Display name for the new resource")] string name,
        [Description("Detailed description of the resource")] string description,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("POST /api/resources name={Name}", name);
        var payload = JsonSerializer.Serialize(new { name, description }, JsonOptions);
        var content = new StringContent(payload, Encoding.UTF8, "application/json");

        var response = await httpClient.PostAsync("api/resources", content, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

